import fs from 'node:fs';import {payloadHash} from '../../execution/ledger.mjs';import {completedTail} from '../run.mjs';import {replayVariant} from '../compare.mjs';
const dir='runtime/moloch/queue-duration-20261014-4',snapshot=JSON.parse(fs.readFileSync(dir+'/state.json')),{hash,...body}=snapshot;if(hash!==payloadHash(body))throw Error('snapshot');const parent=completedTail(snapshot.continuation.parentDirectory);if(parent.snapshot.hash!==snapshot.continuation.parentSnapshotHash)throw Error('parent');
