const output=process.argv[2];if(!output)throw Error('output');fs.writeFileSync(output,JSON.stringify({sourceSnapshotHash:hash,parentSnapshotHash:parent.snapshot.hash,sourceEvents:seq,at:snapshot.state.lastAt,baselineFinancialParity:true,newPaperCapital:'0.000000',results,contestOrders:0,profitabilityEstablished:false,limitations:['Retrospective inherited-bank diagnostic; original live wallets are unchanged.','Both alternatives drain entries and retain original funded quotes and original execution/receipt clocks.','Conditional maker fills and depth-dependent all-or-none exits remain simulated, not actual fills.','No profit is promoted from this sensitivity comparison.']},null,2)+'\n',{flag:'wx'});
